<?php require 'includes/db.php';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$p=$_POST['password']??'';if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($p)<6)$err='Use a valid name, email and password of at least 6 characters.';else{try{$q=$pdo->prepare('INSERT INTO students(name,email,password) VALUES(?,?,?)');$q->execute([$n,$e,password_hash($p,PASSWORD_DEFAULT)]);header('Location: login.php?registered=1');exit;}catch(PDOException $x){$err='This email is already registered.';}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register | ScholarConnect Pro</title><link rel="stylesheet" href="css/style.css"></head><body><?php include 'includes/header.php';?><section class="auth-wrap"><div class="auth-card"><span class="eyebrow">STUDENT ACCOUNT</span><h1>Create Account</h1><?php if($err):?><div class="notice"><?=htmlspecialchars($err)?></div><?php endif;?><form method="post"><label>Full Name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="6" required></label><button class="btn btn-primary">Create Account</button></form><p class="form-link">Already registered? <a href="login.php">Student Login</a></p></div></section><?php include 'includes/footer.php';?></body></html>
